notification.style.display = "block";
notification.style.background = "#4caf50";
notification.style.padding = "1rem";
notification.textContent = "Sukces!";

const computed = window.getComputedStyle(notification);
console.log(computed.display);  // "block" - FAKTYCZNIE zastosowany styl
console.log(computed.fontSize); // np. "16px" - nawet jesli pochodzi z ZEWNETRZNEGO CSS

// zalozmy, ze .card { background-color: #eee; } jest w PLIKU CSS, nie inline
const card = document.querySelector(".card");
console.log(card.style.backgroundColor); // "" - PUSTY string, mimo ze styl JEST zastosowany!

