// Wersja z wieloma inline styles (mniej zalecana):
const notification = document.getElementById("notification");
notification.style.display = "block";
notification.style.background = "#4caf50";
notification.style.padding = "1rem";
notification.style.borderRadius = "4px";

// Wersja z klasa CSS (lepsza praktyka):
// W pliku CSS: .notification-success { display: block; background: #4caf50; padding: 1rem; border-radius: 4px; }
notification.classList.add("notification-success");

// Uzycie gotowej klasy jest lepsza praktyka, poniewaz ROZDZIELA logike
// (KIEDY pokazac dany styl - decyzja podejmowana w JavaScript) od
// samego wygladu (JAKIE dokladnie wartosci CSS sklada sie na ten styl -
// zdefiniowane w pliku CSS). Ulatwia to zarzadzanie wygladem w jednym
// miejscu (pliku CSS) i unika 'rozmycia' logiki stylu pomiedzy JS i CSS.
